create function pg_temp.emergency_policy(enabled boolean,minutes_before int,ack boolean default true) returns jsonb language sql as $$select public.product_command('development.emergency.policy',jsonb_build_object('branch_id','d2000000-0000-4000-8000-000000000001','enabled',enabled,'minutes_before',minutes_before,'synthetic_acknowledged',ack),gen_random_uuid())$$;
