set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.product_command('community.contact.save','{"family_id":"d3000000-0000-4000-8000-000000000001","name":"Synthetic Contact","mobile":"+971500099991","relationship":"Test guardian"}',gen_random_uuid())$$,'Actual guardian command saves the operational emergency contact');
