select throws_ok($$select pg_temp.emergency_policy(true,60)$$,'42501',null,'Owner requires verified AAL2 to configure safety visibility');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000008","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.emergency_policy(true,60)$$,'42501',null,'Head Office requires an explicit development configuration grant');
reset role;
