select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.emergency_policy(true,60)$$,'42501',null,'Branch staff cannot configure coach phone access even with a configuration grant');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select pg_temp.emergency_policy(true,60,false)$$,'22023',null,'Synthetic safety policy requires explicit acknowledgement');
select throws_ok($$select pg_temp.emergency_policy(true,361)$$,'22023',null,'Emergency lead window is bounded to at most six hours');
select lives_ok($$select pg_temp.emergency_policy(true,60)$$,'Verified Owner explicitly enables a bounded branch safety policy');
select is((select count(*)::int from public.development_coach_emergency_contacts),0,'Owner without current coaching assignment gets no coaching projection');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_coach_emergency_contacts),1,'Assigned coach sees the actual rostered child contact within the policy window');
select is((select mobile from public.development_coach_emergency_contacts),'+971500099991','Coach sees the contact saved by the guardian');
